import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ProductSearchServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ProductSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String category = request.getParameter("category");
        String sortBy = request.getParameter("sort");
        String limit = request.getParameter("limit");

        // Input length validation
        if (category != null && category.length() > 100) {
            response.sendError(400, "Category too long");
            return;
        }

        // Allowlist for sort column
        String safeSort = "name";
        if ("price".equals(sortBy) || "rating".equals(sortBy) || "name".equals(sortBy)) {
            safeSort = sortBy;
        }

        // Numeric validation for limit
        int safeLimit = 20;
        try {
            if (limit != null) safeLimit = Math.min(Integer.parseInt(limit), 100);
        } catch (NumberFormatException e) {
            safeLimit = 20;
        }

        // Build query - category is user-controlled and concatenated
        String query = "SELECT id, name, price, description FROM products WHERE category = '" 
                       + category + "' ORDER BY " + safeSort + " LIMIT " + safeLimit;

        logger.info("Executing product search: category=" + category);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout to prevent long-running queries
            stmt.setQueryTimeout(5);

            ResultSet rs = stmt.executeQuery(query);

            response.setContentType("application/json");
            response.setCharacterEncoding("UTF-8");
            PrintWriter out = response.getWriter();
            out.print("{\"products\":[");

            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f,\"description\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getDouble("price"),
                    rs.getString("description").replace("\"", "\\\""));
                first = false;
            }
            out.print("]}");

        } catch (SQLException e) {
            logger.warning("Database error: " + e.getMessage());
            response.setContentType("application/json");
            response.getWriter().print("{\"error\":\"Internal server error\"}");
            response.setStatus(500);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        // POST not supported for search
        response.sendError(405);
    }
}
